const DEFAULT_TITLE = "Thiết bị Minh Quân — Thiết bị xây dựng & công nghiệp | Hà Nội, TP.HCM";
const DEFAULT_DESC = "Thiết bị Minh Quân: máy đo đạc, máy gia công ống, dụng cụ điện và thiết bị công nghiệp. Chọn danh mục bên trái, xem sản phẩm và gọi điện báo giá. Hà Nội và TP.HCM.";
const ALL_INTRO = "Thiết bị Minh Quân cung cấp máy đo đạc, máy gia công ống, dụng cụ điện và thiết bị công nghiệp, tư vấn và báo giá qua điện thoại tại Hà Nội và TP.HCM.";
function updatePageMeta(){
  const qText = (searchInput.value || "").trim();
  const titleEl = document.getElementById("shopTitle");
  const md = document.querySelector('meta[name="description"]');
  if (activeCat && !qText){
    const intro = CAT_INTRO[activeCat] || "";
    document.title = activeCat + " | Thiết bị Minh Quân";
    if (titleEl) titleEl.textContent = activeCat;
    if (categoryIntroEl){ categoryIntroEl.textContent = intro; categoryIntroEl.hidden = !intro; }
    if (md) md.setAttribute("content", intro + " Thiết bị Minh Quân tư vấn và báo giá qua điện thoại tại Hà Nội và TP.HCM.");
    const canon = document.getElementById("canonicalLink"); if (canon) canon.setAttribute("href", "https://thietbiminhquan.com/" + slugify(activeCat));
    const ogT = document.querySelector('meta[property="og:title"]'); if (ogT) ogT.setAttribute("content", activeCat + " | Thiết bị Minh Quân");
    const ogD = document.querySelector('meta[property="og:description"]'); if (ogD) ogD.setAttribute("content", intro + " Thiết bị Minh Quân tư vấn và báo giá qua điện thoại tại Hà Nội và TP.HCM.");
    const ogU = document.querySelector('meta[property="og:url"]'); if (ogU) ogU.setAttribute("content", "https://thietbiminhquan.com/" + slugify(activeCat));
  } else {
    document.title = DEFAULT_TITLE;
    if (titleEl) titleEl.textContent = "Danh mục & sản phẩm";
    if (categoryIntroEl){ categoryIntroEl.textContent = qText ? "" : ALL_INTRO; categoryIntroEl.hidden = !!qText; }
    if (md) md.setAttribute("content", DEFAULT_DESC);
    const canon2 = document.getElementById("canonicalLink"); if (canon2) canon2.setAttribute("href", "https://thietbiminhquan.com/");
    const ogT2 = document.querySelector('meta[property="og:title"]'); if (ogT2) ogT2.setAttribute("content", DEFAULT_TITLE);
    const ogD2 = document.querySelector('meta[property="og:description"]'); if (ogD2) ogD2.setAttribute("content", DEFAULT_DESC);
    const ogU2 = document.querySelector('meta[property="og:url"]'); if (ogU2) ogU2.setAttribute("content", "https://thietbiminhquan.com/");
  }
}

const emptyMsg = document.getElementById("emptyMsg");

function escHtml(s){ return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;"); }
function slugify(s){ return s.replace(/Đ/g,"D").replace(/đ/g,"d").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,""); }
function catFromPath(){ const slug = window.location.pathname.replace(/^\/+|\/+$/g,""); if (!slug || slug === "index.html") return null; return CATEGORIES.find(c => slugify(c) === slug) || null; }
function normSearch(s){ return s.replace(/Đ/g,"D").replace(/đ/g,"d").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase(); }
function setCatUrl(){ const url = activeCat ? "/" + slugify(activeCat) : "/"; if (window.location.pathname !== url) history.pushState(null, "", url); }
function filtered(){
  const qWords = normSearch(searchInput.value || "").trim().split(/\s+/).filter(Boolean);
  const pf = priceFilter.value;
  return PRODUCTS.filter(p => {
    const okCat = qWords.length ? true : (!activeCat || p.cat === activeCat);
    const hay = normSearch(p.name + " " + p.cat);
    const okQ = qWords.every(w => hay.includes(w));
    const okP = pf === "all" || (pf === "priced" ? p.price : !p.price);
    return okCat && okQ && okP;
  });
}
function cardHtml(p, i){
  return `<article class="card">
    <button class="card-img" type="button" data-open="${i}" aria-label="Xem chi tiết ${escHtml(p.name)}"><img src="${p.img}" alt="${escHtml(p.name)}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('img-missing');this.parentElement.setAttribute('data-missing','Ảnh chưa tải được')"></button>
    <div class="card-body">
      <p class="card-cat">${p.cat}</p>
      <h3><button type="button" data-open="${i}">${escHtml(p.name)}</button></h3>
      ${p.price ? `<p class="card-price">${fmt(p.price)}</p>` : ""}
      <div class="card-actions">
        <button class="btn btn-ghost" type="button" data-add="${i}">+ Quan tâm</button>
        <a class="btn btn-primary" href="tel:0932077059">Gọi báo giá</a>
      </div>
    </div>
  </article>`;
}
function renderSidebar(){
  if (activeCat) { for (const g of GROUPS) { if (g.cats.includes(activeCat)) expandedGroups.add(g.name); } }
  const allBtn = `<a class="side-btn${!activeCat ? " active" : ""}" href="/" data-cat="">Tất cả danh mục <span>${PRODUCTS.length}</span></a>`;
  const groupsHtml = GROUPS.map(g => {
    const open = expandedGroups.has(g.name);
    const total = PRODUCTS.filter(p => g.cats.includes(p.cat)).length;
    const subs = g.cats.map(c => {
      const n = PRODUCTS.filter(p => p.cat === c).length;
      return `<a class="side-btn side-sub-btn${activeCat === c ? " active" : ""}" href="/${slugify(c)}" data-cat="${escHtml(c)}">${c} <span>${n}</span></a>`;
    }).join("");
    return `<div class="side-group"><button class="side-group-btn${open ? " open" : ""}" type="button" data-group="${escHtml(g.name)}"><span>${g.name}</span><span class="side-group-meta"><span>${total}</span><span class="side-arrow">${open ? "▾" : "▸"}</span></span></button><div class="side-sub" ${open ? "" : "hidden"}>${subs}</div></div>`;
  }).join("");
  sidebar.innerHTML = allBtn + groupsHtml;
  sidebar.querySelectorAll(".side-group-btn").forEach(b => b.addEventListener("click", () => {
    const name = b.dataset.group;
    if (expandedGroups.has(name)) expandedGroups.delete(name); else expandedGroups.add(name);
    renderSidebar();
  }));
  sidebar.querySelectorAll(".side-sub-btn").forEach(b => b.addEventListener("click", (e) => {
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return; e.preventDefault();
    activeCat = b.dataset.cat; setCatUrl(); renderSidebar(); renderCatalog();
    const el = document.getElementById("floor-" + CATEGORIES.indexOf(activeCat)); if (el) el.scrollIntoView({behavior:"smooth"});
  }));
  sidebar.querySelectorAll(".side-btn[data-cat='']").forEach(b => b.addEventListener("click", (e) => {
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return; e.preventDefault();
    activeCat = null; setCatUrl(); renderSidebar(); renderCatalog();
  }));
}
let expandedGroups = new Set();
function renderCatalog(){
  updatePageMeta();
  const list = filtered();
  const qText = (searchInput.value || "").trim();
  const isAllView = !activeCat && !qText && priceFilter.value === "all";
  resultCount.textContent = qText ? `Tìm “${qText}”: ${list.length} sản phẩm trên toàn shop.` : (activeCat ? `Danh mục: ${activeCat} · ` : "") + `${list.length} sản phẩm.`;
  emptyMsg.hidden = list.length > 0;
  const catsToShow = activeCat && !qText ? [activeCat] : (qText || priceFilter.value !== "all" ? CATEGORIES.filter(c => list.some(p => p.cat === c)) : CATEGORIES);
  catalog.innerHTML = catsToShow.map(c => {
    const items = list.filter(p => p.cat === c);
    const idx = CATEGORIES.indexOf(c);
    const shown = (isAllView && items.length > 4) ? items.slice(0, 4) : items;
    const body = items.length ? `<div class="floor-grid">${shown.map(p => cardHtml(p, PRODUCTS.indexOf(p))).join("")}</div>` + ((isAllView && items.length > 4) ? `<button class="floor-more" type="button" data-showcat="${escHtml(c)}">Xem thêm ${items.length - 4} sản phẩm trong danh mục này →</button>` : "")
      : `<p class="floor-empty">Không có sản phẩm khớp trong danh mục này. Gọi 0932.077.059 để hỏi hàng tương đương.</p>`;
    const countText = (isAllView && items.length > 4) ? `Hiện 4 / ${items.length} sản phẩm` : `${items.length} sản phẩm`;
    return `<section class="floor" id="floor-${idx}"><div class="floor-head"><h2><span class="floor-no">${idx + 1}</span>${c}</h2><span class="floor-count">${countText}</span></div>${body}</section>`;
  }).join("");
  catalog.querySelectorAll("[data-open]").forEach(b => b.addEventListener("click", () => openModal(PRODUCTS[+b.dataset.open])));
  catalog.querySelectorAll("[data-add]").forEach(b => b.addEventListener("click", () => addToCart(PRODUCTS[+b.dataset.add])));
  catalog.querySelectorAll("[data-showcat]").forEach(b => b.addEventListener("click", () => {
    activeCat = b.dataset.showcat; setCatUrl(); renderSidebar(); renderCatalog();
    const el = document.getElementById("floor-" + CATEGORIES.indexOf(activeCat)); if (el) el.scrollIntoView({behavior:"smooth"});
  }));
}
function updateCart(){
  document.getElementById("cartCount").textContent = cart.length;
  document.getElementById("stickyCartCount").textContent = cart.length;
  const listEl = document.getElementById("drawerList");
  listEl.innerHTML = cart.length ? cart.map((p, i) => `<li><span><strong>${escHtml(p.name)}</strong><br><small>${p.cat}${p.price ? " · " + fmt(p.price) : ""}</small></span><button type="button" data-remove="${i}">Xóa</button></li>`).join("")
    : `<li>Chưa có sản phẩm nào. Bấm “+ Quan tâm” ở một sản phẩm để gom tên cần hỏi giá.</li>`;
  listEl.querySelectorAll("[data-remove]").forEach(b => b.addEventListener("click", () => { cart.splice(+b.dataset.remove, 1); updateCart(); }));
}
function addToCart(p){ if (!cart.some(x => x.url === p.url)) cart.push(p); updateCart(); openDrawer(); }
function openDrawer(){ document.getElementById("cartDrawer").hidden = false; document.getElementById("drawerBackdrop").hidden = false; }
function closeDrawer(){ document.getElementById("cartDrawer").hidden = true; document.getElementById("drawerBackdrop").hidden = true; }
function openModal(p){
  modalProduct = p;
  document.getElementById("modalCat").textContent = p.cat;
  document.getElementById("modalCat2").textContent = p.cat;
  document.getElementById("modalName").textContent = p.name;
  const priceEl = document.getElementById("modalPrice"); priceEl.hidden = !p.price; priceEl.textContent = fmt(p.price); priceEl.className = "modal-price";
  document.getElementById("modalDesc").textContent = p.desc;
  document.getElementById("modalImg").src = p.img; document.getElementById("modalImg").alt = p.name;
  document.getElementById("productModal").showModal();
}
document.getElementById("cartBtn").addEventListener("click", openDrawer);
document.getElementById("stickyCartBtn").addEventListener("click", openDrawer);
document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
document.getElementById("drawerBackdrop").addEventListener("click", closeDrawer);
document.getElementById("clearFilter").addEventListener("click", () => { activeCat = null; setCatUrl(); searchInput.value = ""; priceFilter.value = "all"; renderSidebar(); renderCatalog(); });
window.addEventListener("popstate", () => { activeCat = catFromPath(); renderSidebar(); renderCatalog(); });
document.getElementById("modalAdd").addEventListener("click", () => { if (modalProduct) { addToCart(modalProduct); document.getElementById("productModal").close(); } });
document.getElementById("productModal").addEventListener("click", (e) => { if (e.target === document.getElementById("productModal")) document.getElementById("productModal").close(); });
searchInput.addEventListener("input", renderCatalog);
priceFilter.addEventListener("change", renderCatalog);
document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });
activeCat = catFromPath();
renderSidebar(); renderCatalog(); updateCart();
